ARG BASE=python:3.12-slim-bookworm
FROM ${BASE}

ENV DEBIAN_FRONTEND=noninteractive

# Runtime needs only TLS roots, curl (downloads + shim health check) and git.
RUN apt-get update \
 && apt-get install -y --no-install-recommends ca-certificates curl git \
 && rm -rf /var/lib/apt/lists/*

# Self-contained Python under /opt/harness (never touches the base image's python):
# it only runs the local Responses->chat-completions shim (stdlib only).
RUN mkdir -p /opt/harness/bin \
 && curl -LsSf https://astral.sh/uv/install.sh | env UV_UNMANAGED_INSTALL=/opt/harness/uv sh \
 && UV_PYTHON_INSTALL_DIR=/opt/harness/python /opt/harness/uv/uv python install 3.12 \
 && ln -sf "$(UV_PYTHON_INSTALL_DIR=/opt/harness/python UV_PYTHON_PREFERENCE=only-managed /opt/harness/uv/uv python find 3.12)" /opt/harness/bin/harness-python \
 && /opt/harness/bin/harness-python --version

# Harness source (build context = repo root).
COPY . /opt/harness/src

# Install the codex CLI. Compiling the codex-rs workspace needs >8 GB RAM (codex-core/codex-tui
# rustc + final link) and was OOM-killed on the builder, so by default install the official,
# statically linked (musl) release binary that upstream CI builds from this same workspace.
# --build-arg CODEX_INSTALL=source compiles /opt/harness/src/codex-rs instead (>=16 GB builders).
ARG CODEX_RELEASE=rust-v0.156.1
ARG CODEX_INSTALL=release
ARG CARGO_JOBS=2
ARG CARGO_PROFILE=release
RUN set -eu; \
    case "$(uname -m)" in \
      x86_64|amd64) TRIPLE=x86_64-unknown-linux-musl ;; \
      aarch64|arm64) TRIPLE=aarch64-unknown-linux-musl ;; \
      *) echo "unsupported arch $(uname -m)"; exit 1 ;; \
    esac; \
    if [ "$CODEX_INSTALL" = source ]; then \
      apt-get update && apt-get install -y --no-install-recommends build-essential pkg-config cmake libcap-dev libssl-dev; \
      export RUSTUP_HOME=/opt/harness/rust/rustup CARGO_HOME=/opt/harness/rust/cargo CARGO_NET_GIT_FETCH_WITH_CLI=true; \
      curl --proto '=https' --tlsv1.2 -sSf https://sh.rustup.rs | sh -s -- -y --no-modify-path --profile minimal --default-toolchain none; \
      cd /opt/harness/src/codex-rs; \
      /opt/harness/rust/cargo/bin/cargo build --profile "$CARGO_PROFILE" -p codex-cli --bin codex -j "$CARGO_JOBS"; \
      if [ "$CARGO_PROFILE" = dev ]; then OUT=debug; else OUT=$CARGO_PROFILE; fi; \
      install -m 0755 "target/$OUT/codex" /opt/harness/bin/codex; \
      rm -rf target /opt/harness/rust /var/lib/apt/lists/*; \
    else \
      tmp=$(mktemp -d); \
      curl -fsSL --retry 5 -o "$tmp/codex.tar.gz" \
        "https://github.com/openai/codex/releases/download/${CODEX_RELEASE}/codex-${TRIPLE}.tar.gz"; \
      tar -xzf "$tmp/codex.tar.gz" -C "$tmp"; \
      install -m 0755 "$tmp/codex-${TRIPLE}" /opt/harness/bin/codex; \
      rm -rf "$tmp"; \
    fi; \
    /opt/harness/bin/codex --version

# Local shim: codex only speaks the OpenAI Responses API; the proxy speaks chat completions.
COPY <<'EOF' /opt/harness/bin/codex-responses-shim.py
#!/usr/bin/env python3
"""Local OpenAI Responses API -> Chat Completions shim for the Codex CLI.

Codex CLI only speaks the OpenAI Responses API (``POST /v1/responses``); the
recording proxy only speaks chat completions.  This process listens on
loopback, translates each Responses request into a streaming chat-completions
request against ``<upstream>/v1/chat/completions`` and converts the chunk
stream back into the Responses SSE events Codex expects.  Every other path is
forwarded to the upstream unchanged.  Standard library only.
"""

import argparse
import json
import os
import sys
import threading
import time
import urllib.error
import urllib.request
import uuid
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

LOG_LOCK = threading.Lock()
LOG_FILE = None
DUMP_FILE = None
UPSTREAM = "http://127.0.0.1:8080"


def log(msg):
    line = f"[{time.strftime('%H:%M:%S')}] {msg}"
    with LOG_LOCK:
        if LOG_FILE:
            LOG_FILE.write(line + "\n")
            LOG_FILE.flush()
        else:
            sys.stderr.write(line + "\n")
            sys.stderr.flush()


def dump(record):
    if DUMP_FILE is None:
        return
    with LOG_LOCK:
        DUMP_FILE.write(json.dumps(record) + "\n")
        DUMP_FILE.flush()


def new_id(prefix):
    return f"{prefix}_{uuid.uuid4().hex}"


# --------------------------------------------------------------------------
# Request conversion: Responses -> Chat Completions
# --------------------------------------------------------------------------

def content_to_chat(content):
    """Convert a Responses message content list into chat content."""
    if isinstance(content, str):
        return content
    parts = []
    all_text = True
    for part in content or []:
        ptype = part.get("type")
        if ptype in ("input_text", "output_text", "text"):
            parts.append({"type": "text", "text": part.get("text", "")})
        elif ptype == "input_image":
            url = part.get("image_url") or part.get("file_id") or ""
            parts.append({"type": "image_url", "image_url": {"url": url}})
            all_text = False
        elif ptype == "input_audio":
            parts.append({"type": "text", "text": "[audio omitted]"})
        else:
            parts.append({"type": "text", "text": json.dumps(part)})
    if all_text:
        return "".join(p["text"] for p in parts)
    return parts


def output_to_text(output):
    """Flatten a function_call_output payload (string or content items)."""
    if output is None:
        return ""
    if isinstance(output, str):
        return output
    chunks = []
    for part in output:
        if not isinstance(part, dict):
            chunks.append(json.dumps(part))
            continue
        ptype = part.get("type")
        if ptype in ("input_text", "output_text", "text"):
            chunks.append(part.get("text", ""))
        elif ptype == "input_image":
            chunks.append("[image omitted]")
        else:
            chunks.append(json.dumps(part))
    return "\n".join(chunks)


def function_tool(tool):
    fn = {
        "name": tool.get("name", ""),
        "description": tool.get("description", "") or "",
        "parameters": tool.get("parameters") or {"type": "object", "properties": {}},
    }
    return {"type": "function", "function": fn}


def custom_tool_as_function(tool):
    fmt = tool.get("format") or {}
    desc = tool.get("description", "") or ""
    definition = fmt.get("definition") or ""
    syntax = fmt.get("syntax") or fmt.get("type") or "text"
    if definition:
        desc = f"{desc}\n\nThe `input` argument is free-form text that must follow this {syntax} grammar:\n{definition}"
    fn = {
        "name": tool.get("name", ""),
        "description": desc,
        "parameters": {
            "type": "object",
            "properties": {
                "input": {"type": "string", "description": "Raw free-form input for the tool."}
            },
            "required": ["input"],
        },
    }
    return {"type": "function", "function": fn}


def collect_tools(tools, out_tools, custom_names):
    for tool in tools or []:
        ttype = tool.get("type")
        if ttype == "function":
            out_tools.append(function_tool(tool))
        elif ttype == "custom":
            custom_names.add(tool.get("name", ""))
            out_tools.append(custom_tool_as_function(tool))
        elif ttype == "namespace":
            collect_tools(tool.get("tools") or [], out_tools, custom_names)
        else:
            # web_search, tool_search, etc. have no chat-completions equivalent.
            log(f"dropping unsupported tool type {ttype!r}")


def convert_request(req):
    messages = []
    instructions = req.get("instructions")
    if instructions:
        messages.append({"role": "system", "content": instructions})

    chat_tools = []
    custom_names = set()
    collect_tools(req.get("tools") or [], chat_tools, custom_names)

    pending_assistant = None
    for item in req.get("input") or []:
        if not isinstance(item, dict):
            continue
        itype = item.get("type", "message")
        if itype == "message":
            role = item.get("role", "user")
            content = content_to_chat(item.get("content"))
            if role == "assistant":
                msg = {"role": "assistant", "content": content}
                messages.append(msg)
                pending_assistant = msg
            else:
                if role not in ("user", "system"):
                    role = "system" if role == "developer" else "user"
                messages.append({"role": role, "content": content})
                pending_assistant = None
        elif itype in ("function_call", "custom_tool_call"):
            if itype == "function_call":
                arguments = item.get("arguments", "")
                if not isinstance(arguments, str):
                    arguments = json.dumps(arguments)
            else:
                arguments = json.dumps({"input": item.get("input", "")})
            call = {
                "id": item.get("call_id") or new_id("call"),
                "type": "function",
                "function": {"name": item.get("name", ""), "arguments": arguments},
            }
            if pending_assistant is None:
                pending_assistant = {"role": "assistant", "content": ""}
                messages.append(pending_assistant)
            pending_assistant.setdefault("tool_calls", []).append(call)
        elif itype in ("function_call_output", "custom_tool_call_output"):
            messages.append(
                {
                    "role": "tool",
                    "tool_call_id": item.get("call_id") or "",
                    "content": output_to_text(item.get("output")),
                }
            )
            pending_assistant = None
        elif itype == "additional_tools":
            collect_tools(item.get("tools") or [], chat_tools, custom_names)
        else:
            # reasoning, compaction, web_search_call, configuration_update, ...
            continue

    # Chat backends reject assistant messages with empty text and no tool calls.
    cleaned = []
    for msg in messages:
        if msg.get("role") == "assistant":
            has_calls = bool(msg.get("tool_calls"))
            content = msg.get("content")
            empty = content in ("", None, [])
            if empty and not has_calls:
                continue
            if empty and has_calls:
                msg.pop("content", None)
        cleaned.append(msg)

    chat = {"model": req.get("model") or "gpt-5.5", "messages": cleaned}
    if chat_tools:
        chat["tools"] = chat_tools
        tool_choice = req.get("tool_choice")
        if isinstance(tool_choice, str) and tool_choice in ("auto", "none", "required"):
            chat["tool_choice"] = tool_choice
        if "parallel_tool_calls" in req and isinstance(req["parallel_tool_calls"], bool):
            chat["parallel_tool_calls"] = req["parallel_tool_calls"]
    text = req.get("text") or {}
    fmt = text.get("format") if isinstance(text, dict) else None
    if isinstance(fmt, dict) and fmt.get("type") == "json_schema":
        chat["response_format"] = {
            "type": "json_schema",
            "json_schema": {
                "name": fmt.get("name") or "codex_output_schema",
                "schema": fmt.get("schema") or {},
                "strict": bool(fmt.get("strict", False)),
            },
        }
    chat["stream"] = True
    chat["stream_options"] = {"include_usage": True}
    return chat, custom_names


# --------------------------------------------------------------------------
# Response conversion: Chat Completions chunks -> Responses events
# --------------------------------------------------------------------------

def usage_from_chat(usage):
    usage = usage or {}
    prompt = int(usage.get("prompt_tokens") or 0)
    completion = int(usage.get("completion_tokens") or 0)
    total = int(usage.get("total_tokens") or (prompt + completion))
    cached = int((usage.get("prompt_tokens_details") or {}).get("cached_tokens") or 0)
    reasoning = int((usage.get("completion_tokens_details") or {}).get("reasoning_tokens") or 0)
    return {
        "input_tokens": prompt,
        "input_tokens_details": {"cached_tokens": cached},
        "output_tokens": completion,
        "output_tokens_details": {"reasoning_tokens": reasoning},
        "total_tokens": total,
    }


class ResponseBuilder:
    """Accumulates chat chunks and emits Responses SSE events."""

    def __init__(self, emit, model, custom_names):
        self.emit = emit
        self.model = model
        self.custom_names = custom_names
        self.response_id = new_id("resp")
        self.seq = 0
        self.output = []
        self.text = ""
        self.message_id = None
        self.tool_calls = {}  # index -> {id, name, arguments}
        self.tool_order = []
        self.usage = None
        self.finish_reason = None

    def event(self, etype, **fields):
        payload = {"type": etype, "sequence_number": self.seq}
        self.seq += 1
        payload.update(fields)
        self.emit(etype, payload)

    def start(self):
        self.event(
            "response.created",
            response={
                "id": self.response_id,
                "object": "response",
                "created_at": int(time.time()),
                "status": "in_progress",
                "model": self.model,
                "output": [],
            },
        )

    def on_chunk(self, chunk):
        if chunk.get("usage"):
            self.usage = chunk["usage"]
        for choice in chunk.get("choices") or []:
            delta = choice.get("delta") or {}
            content = delta.get("content")
            if content:
                if self.message_id is None:
                    self.message_id = new_id("msg")
                    self.event(
                        "response.output_item.added",
                        output_index=len(self.output),
                        item={
                            "type": "message",
                            "id": self.message_id,
                            "role": "assistant",
                            "status": "in_progress",
                            "content": [],
                        },
                    )
                self.text += content
                self.event(
                    "response.output_text.delta",
                    item_id=self.message_id,
                    output_index=len(self.output),
                    content_index=0,
                    delta=content,
                )
            for call in delta.get("tool_calls") or []:
                idx = call.get("index", 0)
                entry = self.tool_calls.get(idx)
                if entry is None:
                    entry = {"id": None, "name": "", "arguments": ""}
                    self.tool_calls[idx] = entry
                    self.tool_order.append(idx)
                if call.get("id"):
                    entry["id"] = call["id"]
                fn = call.get("function") or {}
                if fn.get("name") and not entry["name"]:
                    entry["name"] = fn["name"]
                if fn.get("arguments"):
                    entry["arguments"] += fn["arguments"]
            if choice.get("finish_reason"):
                self.finish_reason = choice["finish_reason"]

    def finish_message(self):
        if self.message_id is None:
            return
        item = {
            "type": "message",
            "id": self.message_id,
            "role": "assistant",
            "status": "completed",
            "content": [{"type": "output_text", "text": self.text}],
        }
        self.event(
            "response.output_text.done",
            item_id=self.message_id,
            output_index=len(self.output),
            content_index=0,
            text=self.text,
        )
        self.event("response.output_item.done", output_index=len(self.output), item=item)
        self.output.append(item)
        self.message_id = None

    def finish_tool_calls(self):
        for idx in self.tool_order:
            entry = self.tool_calls[idx]
            call_id = entry["id"] or new_id("call")
            name = entry["name"]
            arguments = entry["arguments"]
            if name in self.custom_names:
                raw_input = arguments
                try:
                    parsed = json.loads(arguments) if arguments else {}
                    if isinstance(parsed, dict) and isinstance(parsed.get("input"), str):
                        raw_input = parsed["input"]
                except (ValueError, TypeError):
                    pass
                item = {
                    "type": "custom_tool_call",
                    "id": new_id("ctc"),
                    "call_id": call_id,
                    "name": name,
                    "input": raw_input,
                    "status": "completed",
                }
            else:
                item = {
                    "type": "function_call",
                    "id": new_id("fc"),
                    "call_id": call_id,
                    "name": name,
                    "arguments": arguments if arguments else "{}",
                    "status": "completed",
                }
            self.event(
                "response.output_item.added",
                output_index=len(self.output),
                item=dict(item, status="in_progress"),
            )
            self.event("response.output_item.done", output_index=len(self.output), item=item)
            self.output.append(item)
        self.tool_calls = {}
        self.tool_order = []

    def complete(self):
        self.finish_message()
        self.finish_tool_calls()
        response = {
            "id": self.response_id,
            "object": "response",
            "created_at": int(time.time()),
            "status": "completed",
            "model": self.model,
            "output": self.output,
            "usage": usage_from_chat(self.usage),
        }
        self.event("response.completed", response=response)
        return response

    def fail(self, code, message):
        response = {
            "id": self.response_id,
            "object": "response",
            "status": "failed",
            "error": {"code": code, "message": message},
        }
        self.event("response.failed", response=response)


# --------------------------------------------------------------------------
# HTTP server
# --------------------------------------------------------------------------

def upstream_url(path):
    return UPSTREAM.rstrip("/") + path


HOP_BY_HOP = {
    "connection",
    "keep-alive",
    "proxy-authenticate",
    "proxy-authorization",
    "te",
    "trailers",
    "transfer-encoding",
    "upgrade",
    "host",
    "content-length",
    "accept-encoding",
}


def forward_headers(headers):
    out = {}
    for key, value in headers.items():
        if key.lower() in HOP_BY_HOP:
            continue
        out[key] = value
    return out


def iter_sse_data(stream):
    """Yield the JSON payload of each `data:` line in an SSE stream."""
    for raw in stream:
        line = raw.rstrip(b"\r\n")
        if not line:
            continue
        if line.startswith(b"data:"):
            data = line[5:].strip()
            if data == b"[DONE]":
                return
            if data:
                try:
                    yield json.loads(data)
                except ValueError:
                    log(f"ignoring non-JSON SSE data: {data[:200]!r}")
        # comments / event: lines are ignored


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"
    server_version = "codex-responses-shim/1.0"

    def log_message(self, fmt, *args):  # quieter default logging
        log(f"{self.address_string()} {fmt % args}")

    def read_body(self):
        length = int(self.headers.get("Content-Length") or 0)
        return self.rfile.read(length) if length else b""

    def send_json(self, status, payload):
        data = json.dumps(payload).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(data)))
        self.send_header("Connection", "close")
        self.end_headers()
        self.wfile.write(data)

    def do_GET(self):
        if self.path in ("/healthz", "/health"):
            self.send_json(200, {"ok": True, "upstream": UPSTREAM})
            return
        self.passthrough(b"")

    def do_POST(self):
        body = self.read_body()
        if self.path.rstrip("/").endswith("/responses"):
            self.handle_responses(body)
            return
        self.passthrough(body)

    def passthrough(self, body):
        url = upstream_url(self.path)
        req = urllib.request.Request(url, data=body or None, method=self.command)
        for key, value in forward_headers(self.headers).items():
            req.add_header(key, value)
        try:
            with urllib.request.urlopen(req, timeout=600) as resp:
                data = resp.read()
                self.send_response(resp.status)
                for key, value in resp.headers.items():
                    if key.lower() in HOP_BY_HOP or key.lower() == "content-encoding":
                        continue
                    self.send_header(key, value)
                self.send_header("Content-Length", str(len(data)))
                self.send_header("Connection", "close")
                self.end_headers()
                self.wfile.write(data)
        except urllib.error.HTTPError as err:
            data = err.read()
            self.send_response(err.code)
            self.send_header("Content-Type", err.headers.get("Content-Type", "application/json"))
            self.send_header("Content-Length", str(len(data)))
            self.send_header("Connection", "close")
            self.end_headers()
            self.wfile.write(data)
        except Exception as err:  # noqa: BLE001
            log(f"passthrough {self.command} {self.path} failed: {err}")
            self.send_json(502, {"error": {"message": f"upstream error: {err}", "type": "server_error"}})

    def handle_responses(self, body):
        try:
            req = json.loads(body.decode("utf-8") or "{}")
        except ValueError as err:
            self.send_json(400, {"error": {"message": f"invalid JSON body: {err}", "type": "invalid_request_error"}})
            return

        chat, custom_names = convert_request(req)
        want_stream = bool(req.get("stream", True))
        model = chat["model"]
        log(f"responses request: model={model} input_items={len(req.get('input') or [])} tools={len(chat.get('tools') or [])}")
        dump({"kind": "chat_request", "ts": time.time(), "chat": chat})

        url = upstream_url("/v1/chat/completions")
        data = json.dumps(chat).encode()
        upstream_req = urllib.request.Request(url, data=data, method="POST")
        upstream_req.add_header("Content-Type", "application/json")
        auth = self.headers.get("Authorization")
        if auth:
            upstream_req.add_header("Authorization", auth)
        else:
            upstream_req.add_header("Authorization", f"Bearer {os.environ.get('PROXY_API_KEY', 'proxy')}")
        upstream_req.add_header("Accept", "text/event-stream")

        try:
            resp = urllib.request.urlopen(upstream_req, timeout=3600)
        except urllib.error.HTTPError as err:
            raw = err.read()
            log(f"upstream HTTP {err.code}: {raw[:500]!r}")
            try:
                payload = json.loads(raw.decode("utf-8"))
            except ValueError:
                payload = {"error": {"message": raw.decode("utf-8", "replace")[:2000], "type": "server_error"}}
            if "error" not in payload:
                payload = {"error": {"message": json.dumps(payload)[:2000], "type": "server_error"}}
            self.send_json(err.code, payload)
            return
        except Exception as err:  # noqa: BLE001
            log(f"upstream connection failed: {err}")
            self.send_json(502, {"error": {"message": f"upstream connection failed: {err}", "type": "server_error"}})
            return

        collected = []

        def emit_stream(etype, payload):
            chunk = f"event: {etype}\ndata: {json.dumps(payload)}\n\n".encode()
            self.wfile.write(f"{len(chunk):x}\r\n".encode() + chunk + b"\r\n")
            self.wfile.flush()

        def emit_collect(etype, payload):
            collected.append(payload)

        builder = ResponseBuilder(emit_stream if want_stream else emit_collect, model, custom_names)

        if want_stream:
            self.send_response(200)
            self.send_header("Content-Type", "text/event-stream")
            self.send_header("Cache-Control", "no-cache")
            self.send_header("Transfer-Encoding", "chunked")
            self.send_header("Connection", "close")
            self.end_headers()

        builder.start()
        final = None
        try:
            with resp:
                content_type = resp.headers.get("Content-Type", "")
                if "text/event-stream" in content_type:
                    for chunk in iter_sse_data(resp):
                        builder.on_chunk(chunk)
                else:
                    # Non-streaming upstream reply: treat the single completion as one chunk.
                    payload = json.loads(resp.read().decode("utf-8"))
                    for choice in payload.get("choices") or []:
                        msg = choice.get("message") or {}
                        pseudo = {
                            "choices": [
                                {
                                    "delta": {
                                        "content": msg.get("content"),
                                        "tool_calls": [
                                            dict(tc, index=i) for i, tc in enumerate(msg.get("tool_calls") or [])
                                        ],
                                    },
                                    "finish_reason": choice.get("finish_reason"),
                                }
                            ],
                            "usage": payload.get("usage"),
                        }
                        builder.on_chunk(pseudo)
            final = builder.complete()
            dump({"kind": "response", "ts": time.time(), "response": final})
        except Exception as err:  # noqa: BLE001
            log(f"stream conversion failed: {err}")
            try:
                builder.fail("server_error", f"shim stream failure: {err}")
            except Exception:  # noqa: BLE001
                pass

        if want_stream:
            try:
                self.wfile.write(b"0\r\n\r\n")
                self.wfile.flush()
            except Exception:  # noqa: BLE001
                pass
        else:
            if final is None:
                self.send_json(502, {"error": {"message": "shim stream failure", "type": "server_error"}})
            else:
                self.send_json(200, final)


def main():
    global LOG_FILE, DUMP_FILE, UPSTREAM
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--listen", default="127.0.0.1:8790", help="host:port to listen on")
    parser.add_argument("--upstream", default=os.environ.get("PROXY_URL", "http://127.0.0.1:8080"),
                        help="proxy root URL (chat completions at <upstream>/v1/chat/completions)")
    parser.add_argument("--log", default=None, help="log file (default: stderr)")
    parser.add_argument("--dump", default=None, help="JSONL file recording converted requests/responses")
    args = parser.parse_args()

    UPSTREAM = args.upstream
    if args.log:
        LOG_FILE = open(args.log, "a", encoding="utf-8")
    if args.dump:
        DUMP_FILE = open(args.dump, "a", encoding="utf-8")

    host, _, port = args.listen.rpartition(":")
    server = ThreadingHTTPServer((host or "127.0.0.1", int(port)), Handler)
    server.daemon_threads = True
    log(f"listening on {args.listen}, upstream {UPSTREAM}")
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass


if __name__ == "__main__":
    main()
